package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.nio.file.*;
public class NativeUiFieldDiagnosticsTest {
 void add(NativeUiFieldDiagnostics.Accumulator a,int i,int parent,int depth,String resource,String text,String desc,boolean visible){a.node(i,parent,depth,0,0,100,100,visible,true,false,"android.widget.TextView",resource,text,desc);}
 NativeUiFieldDiagnostics.Result sample(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,"homePageWrapper","", "",true);add(a,1,0,1,"read","", "",true);add(a,2,1,2,null,"Read to earn", "0/30",true);return a.result();}
 @Test public void exactAliasVersusGenericClue(){assertEquals(NativeUiFieldDiagnostics.Alias.READ_TITLE_EN,NativeUiFieldDiagnostics.field("Read to earn").alias());var f=NativeUiFieldDiagnostics.field("Read to earn\n");assertEquals(NativeUiFieldDiagnostics.Alias.NONE,f.alias());assertTrue((f.mask()&NativeUiFieldDiagnostics.READING)!=0);}
 @Test public void tokensDistinguishWholePrefixContains(){var a=NativeUiFieldDiagnostics.field("Search");assertEquals(1,a.wholeTokens());assertEquals(1,a.prefixTokens());assertEquals(1,a.containsTokens());var b=NativeUiFieldDiagnostics.field("Search more");assertEquals(0,b.wholeTokens());assertEquals(1,b.prefixTokens());var c=NativeUiFieldDiagnostics.field("Please Search");assertEquals(0,c.prefixTokens());assertEquals(1,c.containsTokens());}
 @Test public void delimiterAndControlCounts(){var f=NativeUiFieldDiagnostics.field("Read\r\n\u00a0,，/\u202e\u2066");assertEquals(1,f.newlines());assertEquals(1,f.carriageReturns());assertEquals(1,f.nbsp());assertEquals(2,f.commas());assertEquals(1,f.slashes());assertEquals(2,f.bidi());}
 @Test public void pureFractionOnlyExportsBoundedUnattributedValues(){var f=NativeUiFieldDiagnostics.field("0 / 30");assertEquals(0,f.numerator());assertEquals(30,f.denominator());assertEquals(-1,NativeUiFieldDiagnostics.field("Read 0/30").numerator());assertEquals(-1,NativeUiFieldDiagnostics.field("points 27").numerator());}
 @Test public void invalidFractionNumbersRemainShapeOnly(){for(String s:List.of("31/30","10001/10001","9999999999/9999999999")){var f=NativeUiFieldDiagnostics.field(s);assertTrue((f.mask()&8)!=0);assertEquals(-1,f.numerator());assertEquals(-1,f.denominator());}assertEquals(0,NativeUiFieldDiagnostics.field("0/0").denominator());}
 @Test public void strictFullGrammarCountsVisibleAndHiddenSeparately(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,null,"", "",true);add(a,1,0,1,null,"Read to earn, , 0 out of 30 points earned","",false);add(a,2,0,1,null,"Search to earn, Search in Bing everyday to earn Rewards points, 0 out of 60 points earned","",true);add(a,3,0,1,null,"Read to earn, 30 points earned","",true);var r=a.result();assertEquals(1,r.strictReadHidden());assertEquals(0,r.strictReadVisible());assertEquals(1,r.strictSearchVisible());assertEquals(0,r.strictSearchHidden());assertEquals(-1,r.nodes().get(1).text().numerator());}
 @Test public void identicalTextDescriptionCountsNodeOnce(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,null,"Read to earn, , 0 out of 30 points earned","Read to earn, , 0 out of 30 points earned",true);assertEquals(1,a.result().strictReadVisible());}
 @Test public void actualIndicesParentsAndBoundsPreserved(){var r=sample();assertEquals(3,r.nodes().size());assertEquals(2,r.nodes().get(2).index());assertEquals(1,r.nodes().get(2).parent());assertEquals(2,r.nodes().get(2).depth());assertEquals(100,r.nodes().get(2).right());}
 @Test public void pureFractionDoesNotBecomeTaskCounter(){var r=sample();assertEquals(1,r.fractionCandidates());assertTrue(r.summary().contains("numbers=UNATTRIBUTED"));assertTrue(r.summary().contains("counterAuthority=false actionAuthority=false"));}
 @Test public void resourceWhitelistNoneAndOtherRemainDistinct(){assertEquals(NativeUiFieldDiagnostics.Resource.NONE,NativeUiFieldDiagnostics.resource(null));assertEquals(NativeUiFieldDiagnostics.Resource.NONE,NativeUiFieldDiagnostics.resource(""));assertEquals(NativeUiFieldDiagnostics.Resource.OTHER,NativeUiFieldDiagnostics.resource("private.custom.id"));for(String s:List.of("homePageWrapper","dailyTaskPanel","dailyActivities","search","read"))assertTrue(NativeUiFieldDiagnostics.knownResource(NativeUiFieldDiagnostics.resource(s)));assertFalse(NativeUiFieldDiagnostics.knownResource(NativeUiFieldDiagnostics.Resource.NONE));}
 @Test public void blankCandidateRequiresActualKnownParent(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,"dailyActivities","","",true);add(a,1,0,1,null,"","",true);add(a,2,0,1,"unknown","","",true);var r=a.result();assertEquals(2,r.blankScopedNodes());assertEquals(1,r.knownResources());assertTrue(r.nodes().get(1).blankScoped());}
 @Test public void absentResourceAloneIsNotCandidate(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,null,"","",true);add(a,1,0,1,null,"","",true);assertEquals(0,a.result().totalCandidates());assertTrue(a.result().nodes().isEmpty());}
 @Test public void roundTripNoRawTextOrArbitraryId(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,"private.id","secret Search account", "",true);var r=a.result();String wire=NativeUiFieldDiagnostics.encode(r);assertEquals(r,NativeUiFieldDiagnostics.parse(wire));assertFalse(r.summary().contains("secret"));assertFalse(wire.contains("private"));assertTrue(wire.matches("[0-9,;\\-]+"));}
 @Test public void outputCapDoesNotTruncateCountsAndTaskCluePriority(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,null,"","",true);for(int i=1;i<=60;i++)add(a,i,0,1,null,"0/30","",true);add(a,61,0,1,null,"Read to earn","",true);var r=a.result();assertEquals(61,r.totalCandidates());assertEquals(60,r.fractionCandidates());assertTrue(r.truncated());assertTrue(r.nodes().size()<=24);assertTrue(r.nodes().stream().anyMatch(n->n.index()==61));assertEquals(r.totalCandidates()-(int)r.nodes().stream().filter(n->n.candidate()).count(),r.omittedCandidates());assertEquals(r,NativeUiFieldDiagnostics.parse(NativeUiFieldDiagnostics.encode(r)));}
 @Test public void parentsLimitedToThreeActualLevels(){var a=new NativeUiFieldDiagnostics.Accumulator();for(int i=0;i<6;i++)add(a,i,i-1,i,null,i==5?"Search":"","",true);var r=a.result();assertEquals(List.of(2,3,4,5),r.nodes().stream().map(n->n.index()).toList());assertEquals(1,r.nodes().get(0).parent());}
 @Test public void emptyFailureResultRoundTrips(){var r=new NativeUiFieldDiagnostics.Accumulator().result();assertEquals(0,r.totalNodes());assertEquals(r,NativeUiFieldDiagnostics.parse(NativeUiFieldDiagnostics.encode(r)));}
 @Test(expected=IllegalArgumentException.class)public void duplicateWireRecordsRejected(){String s=NativeUiFieldDiagnostics.encode(sample());String[] r=s.split(";");NativeUiFieldDiagnostics.parse(s+";"+r[1]);}
 @Test(expected=IllegalArgumentException.class)public void forgedOmissionRejected(){String s=NativeUiFieldDiagnostics.encode(sample());String[] rows=s.split(";",-1),h=rows[0].split(",");h[11]="1";h[12]="1";rows[0]=String.join(",",h);NativeUiFieldDiagnostics.parse(String.join(";",rows));}
 @Test(expected=IllegalArgumentException.class)public void overlongTailRejected(){NativeUiFieldDiagnostics.parse("1".repeat(12001));}
 @Test(expected=IllegalArgumentException.class)public void parentCannotBeSelf(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,0,0,null,"Read","",true);}
 @Test(expected=IllegalArgumentException.class)public void depthMustMatchActualParent(){var a=new NativeUiFieldDiagnostics.Accumulator();add(a,0,-1,0,null,"","",true);add(a,1,0,2,null,"Read","",true);}
 @Test(expected=IllegalArgumentException.class)public void fieldBoundPreserved(){NativeUiFieldDiagnostics.field("x".repeat(2049));}
 @Test public void helperUsesOriginalRelationAndNeverParserForV51()throws Exception{String s=Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/NativeUiStructureHelper.java"));assertTrue(s.contains("boolean fieldMode=readyMode&&\"DIAGNOSTIC_V51\".equals(args[2])"));assertTrue(s.contains("if(!fieldMode){if(!readyMode||!diagnostics.blocked())"));assertTrue(s.contains("fieldDiagnostics.node(current.index(),current.parent(),current.depth()"));assertTrue(s.contains("node.getBoundsInScreen(originalBounds)"));assertTrue(s.contains("fieldMode?fieldDiagnostics.result():null"));}
 @Test public void resourceCapabilityOnlyForV51AndReadBack()throws Exception{String s=Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/NativeUiStructureHelper.java"));assertTrue(s.contains("fieldMode ? AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS : 0"));assertTrue(s.contains("readback.flags != requiredFlags"));}
}
